1	package cli
2	
3	import (
4		"crypto/sha256"
5		"encoding/hex"
6		"encoding/json"
7		"fmt"
8		"io/fs"
9		"os"
10		"path/filepath"
11		"strings"
12		"time"
13	
14		"github.com/entireio/entire-brain/internal/cli/internal/base"
15		"github.com/entireio/entire-brain/internal/cli/internal/brainstore"
16		bmanifest "github.com/entireio/entire-brain/internal/cli/internal/manifest"
17	)
18	
19	// doc.go is the `doc` source: it indexes the brain's own markdown — the
20	// agent-synthesized seed summaries plus the copied repo docs under seed/docs/ —
21	// into retrievable chunks. Facts/history cover session-derived work; docs cover
22	// the written/designed knowledge sessions don't, and give the brain a way to
23	// retrieve its own documentation (qmd's core use case). The index is a derived,
24	// rebuildable artifact, like the history index.
25	
26	const (
27		docDirName       = "docs"
28		docIndexFileName = "index.json"
29		docIndexPath     = docDirName + "/" + docIndexFileName
30		maxDocChunkBytes = 3000 // ~750 tokens, qmd-scale chunks
31	)
32	
33	// A doc index aggregates multiple seed documents, so use the general 64 MiB
34	// ceiling rather than the smaller manifest limit. Variable for boundary tests.
35	var maxDocIndexBytes int64 = base.DefaultMaxReadBytes
36	
37	type docIndex struct {
38		GeneratedAt time.Time   `json:"generated_at"`
39		Records     []docRecord `json:"records"`
40	}
41	
42	type docRecord struct {
43		ID         string `json:"id"`
44		Path       string `json:"path"`    // brain-relative markdown path
45		Heading    string `json:"heading"` // first markdown heading within the chunk, if any (empty when the chunk starts mid-section)
46		Line       int    `json:"line"`    // 1-based start line in the file
47		Text       string `json:"text"`
48		Historical bool   `json:"historical,omitempty"` // explicitly superseded reference material; current docs rank first
49	}
50	
51	// Historical documents are untrusted context, not forbidden context. Apply a
52	// bounded relevance discount so equally relevant current material wins while a
53	// much stronger historical match remains discoverable and carries its explicit
54	// verification caveat.
55	func docTrustAdjustedScore(score float64, historical bool) float64 {
56		if historical {
57			if score < 0 {
58				return score / 0.85
59			}
60			return score * 0.85
61		}
62		return score
63	}
64	
65	func docRecordID(path string, line int, text string) string {
66		sum := sha256.Sum256([]byte(fmt.Sprintf("%s\x00%d\x00%s", path, line, text)))
67		return hex.EncodeToString(sum[:])[:12]
68	}
69	
70	// firstHeading returns the first markdown heading in a chunk (without the leading
71	// #s), so a retrieved chunk can be labeled with its section.
72	func firstHeading(text string) string {
73		for _, line := range strings.Split(text, "\n") {
74			t := strings.TrimSpace(line)
75			if strings.HasPrefix(t, "#") {
76				return strings.TrimSpace(strings.TrimLeft(t, "#"))
77			}
78		}
79		return ""
80	}
81	
82	// loadDocRecordsFromSeed scans every markdown file under brain/seed and chunks it
83	// into doc records. Size-based chunking (qmd-style) keeps it simple and robust.
84	// Per-file walk/read failures are collected as warnings (not hard errors, so one
85	// unreadable file doesn't lose the whole index) and surfaced via the manifest.
86	func loadDocRecordsFromSeed(brainDir string) (records []docRecord, files int, warnings []string, err error) {
87		seedDir := filepath.Join(brainDir, seedDirName)
88		info, statErr := os.Lstat(seedDir)
89		if statErr != nil {
90			if os.IsNotExist(statErr) {
91				return nil, 0, nil, nil // no seed yet; not an error
92			}
93			return nil, 0, nil, statErr // a real stat failure (e.g. permissions) must not look like an empty index
94		}
95		if info.Mode()&os.ModeSymlink != 0 {
96			return nil, 0, []string{"skip seed: path component must not be a symlink: seed"}, nil
97		}
98		relTo := func(path string) string {
99			if rel, relErr := filepath.Rel(brainDir, path); relErr == nil {
100				return filepath.ToSlash(rel)
101			}
102			return path
103		}
104		err = filepath.WalkDir(seedDir, func(path string, d fs.DirEntry, walkErr error) error {
105			if walkErr != nil {
106				warnings = append(warnings, fmt.Sprintf("walk %s: %v", relTo(path), walkErr))
107				return nil
108			}
109			if d.IsDir() || !strings.HasSuffix(strings.ToLower(path), ".md") {
110				return nil
111			}
112			rel := relTo(path)
113			clean := filepath.Clean(filepath.FromSlash(rel))
114			if err := base.RejectSymlinkPathComponents(brainDir, clean); err != nil {
115				warnings = append(warnings, fmt.Sprintf("skip %s: %v", rel, err))
116				return nil
117			}
118			data, rErr := base.SafeReadFile(path, base.MaxSeedDocBytes)
119			if rErr != nil {
120				warnings = append(warnings, fmt.Sprintf("read %s: %v", rel, rErr))
121				return nil
122			}
123			files++
124			historical := docFileHistorical(rel, string(data))
125			for _, c := range chunkLines(string(data), maxDocChunkBytes, false) {
126				if strings.TrimSpace(c.Text) == "" {
127					continue
128				}
129				// Trim only the trailing newline the chunker appends — keep leading
130				// indentation so an indented code block / nested list that a chunk starts
131				// inside isn't corrupted (and the hashed id stays faithful to the source).
132				text := strings.TrimRight(c.Text, "\n")
133				records = append(records, docRecord{
134					ID:         docRecordID(rel, c.StartLine, text),
135					Path:       rel,
136					Heading:    firstHeading(text),
137					Line:       c.StartLine,
138					Text:       text,
139					Historical: historical,
140				})
141			}
142			return nil
143		})
144		return records, files, warnings, err
145	}
146	
147	func docFileHistorical(path, text string) bool {
148		lowerPath := "/" + strings.ToLower(filepath.ToSlash(path)) + "/"
149		for _, marker := range []string{"/archive/", "/historical/", "/outdated/", "/deprecated/"} {
150			if strings.Contains(lowerPath, marker) {
151				return true
152			}
153		}
154		markerText := strings.ToLower(text)
155		if len(markerText) > 2000 {
156			markerText = markerText[:2000]
157		}
158		return strings.Contains(markerText, "<!-- entire-brain-status: historical -->") ||
159			strings.Contains(markerText, "<!-- entire-brain-status: superseded -->")
160	}
161	
162	// writeDocIndexAndSource builds and persists the doc index + manifest source from
163	// the seed markdown. It mirrors writeBrainHistoryIndexAndSource.
164	func writeDocIndexAndSource(brainDir string, now time.Time) (*docSourceManifest, error) {
165		var source *docSourceManifest
166		err := brainstore.WithBrainWriteLock(brainDir, func() error {
167			var runErr error
168			source, runErr = writeDocIndexAndSourceLocked(brainDir, now)
169			return runErr
170		})
171		return source, err
172	}
173	
174	func writeDocIndexAndSourceLocked(brainDir string, now time.Time) (*docSourceManifest, error) {
175		records, files, warnings, err := loadDocRecordsFromSeed(brainDir)
176		if err != nil {
177			return nil, err
178		}
179		index := docIndex{GeneratedAt: now, Records: records}
180		data, err := json.MarshalIndent(index, "", "  ")
181		if err != nil {
182			return nil, err
183		}
184		data = append(data, '\n')
185		if int64(len(data)) > maxDocIndexBytes {
186			return nil, &readBoundExceededError{Source: docIndexPath, Max: maxDocIndexBytes}
187		}
188		if err := brainstore.WriteBrainRelativeFileAtomic(brainDir, docIndexPath, data, 0o600); err != nil {
189			return nil, fmt.Errorf("write doc index: %w", err)
190		}
191		source := &docSourceManifest{GeneratedAt: now, IndexPath: docIndexPath, Records: len(records), Files: files, Warnings: warnings}
192		// Build the derived BM25 index alongside its truth (best-effort).
193		if db, ftsErr := openDocFTSLocked(brainDir, index); ftsErr == nil {
194			_ = db.Close()
195		}
196		manifest, err := bmanifest.Load(brainDir)
197		if err != nil {
198			return nil, err
199		}
200		if manifest.Sources == nil {
201			manifest.Sources = &brainSources{}
202		}
203		manifest.Sources.Docs = source
204		if manifest.GeneratedAt.IsZero() {
205			manifest.GeneratedAt = now
206		}
207		if err := writeBrainManifestAndReadme(brainDir, *manifest); err != nil {
208			return nil, err
209		}
210		return source, nil
211	}
212	
213	// verifyDeclaredDocIndex reports why the docs index a manifest declares cannot
214	// be read. It probes exactly the file loadDocIndex opens, so a "docs: ok"
215	// status is a statement about the bytes retrieval will actually rank, not about
216	// a manifest field. Retrieval treats a missing index as an empty docs layer
217	// (os.IsNotExist is skipped, not raised), so without this check a deleted or
218	// unreadable index is indistinguishable from "nothing matched".
219	func verifyDeclaredDocIndex(brainDir string) error {
220		f, err := openDeclaredDocIndex(brainDir)
221		if err != nil {
222			return err
223		}
224		return f.Close()
225	}
226	
227	// Both diagnostics and queries must validate the descriptor they actually use.
228	func openDeclaredDocIndex(brainDir string) (*os.File, error) {
229		path := filepath.Join(brainDir, filepath.FromSlash(docIndexPath))
230		if err := base.RejectExistingSymlinkPathComponents(brainDir, docIndexPath); err != nil {
231			return nil, err
232		}
233		before, err := os.Lstat(path)
234		if err != nil {
235			return nil, err
236		}
237		if !before.Mode().IsRegular() {
238			return nil, fmt.Errorf("%s is not a regular file", docIndexPath)
239		}
240		// Nonblocking/no-follow open also covers a swap after the path checks.
241		f, err := os.OpenFile(path, os.O_RDONLY|base.FileLockOpenFlags()|base.MemoryStateReadOpenFlags(), 0)
242		if err != nil {
243			return nil, err
244		}
245		opened, err := f.Stat()
246		if err != nil {
247			f.Close()
248			return nil, err
249		}
250		if !opened.Mode().IsRegular() || !os.SameFile(before, opened) {
251			f.Close()
252			return nil, fmt.Errorf("%s changed while opening", docIndexPath)
253		}
254		if opened.Size() > maxDocIndexBytes {
255			f.Close()
256			return nil, &readBoundExceededError{Source: docIndexPath, Max: maxDocIndexBytes}
257		}
258		if err := base.RejectOpenFileAlias(path, f, docIndexPath); err != nil {
259			f.Close()
260			return nil, err
261		}
262		return f, nil
263	}
264	
265	func loadDocIndex(brainDir string) (docIndex, error) {
266		var index docIndex
267		f, err := openDeclaredDocIndex(brainDir)
268		if err != nil {
269			return index, err
270		}
271		defer f.Close()
272		data, err := base.SafeReadAll(f, maxDocIndexBytes, docIndexPath)
273		if err != nil {
274			return index, err
275		}
276		return index, json.Unmarshal(data, &index)
277	}
