96			return nil, 0, []string{"skip seed: path component must not be a symlink: seed"}, nil
97		}
98		relTo := func(path string) string {
99			if rel, relErr := filepath.Rel(brainDir, path); relErr == nil {
100				return filepath.ToSlash(rel)
101			}
102			return path
103		}
104		err = filepath.WalkDir(seedDir, func(path string, d fs.DirEntry, walkErr error) error {
105			if walkErr != nil {
106				warnings = append(warnings, fmt.Sprintf("walk %s: %v", relTo(path), walkErr))
107				return nil
108			}
109			if d.IsDir() || !strings.HasSuffix(strings.ToLower(path), ".md") {
110				return nil
111			}
112			rel := relTo(path)
113			clean := filepath.Clean(filepath.FromSlash(rel))
114			if err := base.RejectSymlinkPathComponents(brainDir, clean); err != nil {
115				warnings = append(warnings, fmt.Sprintf("skip %s: %v", rel, err))
116				return nil
117			}
118			data, rErr := base.SafeReadFile(path, base.MaxSeedDocBytes)
119			if rErr != nil {
120				warnings = append(warnings, fmt.Sprintf("read %s: %v", rel, rErr))
121				return nil
122			}
123			files++
124			historical := docFileHistorical(rel, string(data))
125			for _, c := range chunkLines(string(data), maxDocChunkBytes, false) {
126				if strings.TrimSpace(c.Text) == "" {
127					continue
128				}
129				// Trim only the trailing newline the chunker appends — keep leading
130				// indentation so an indented code block / nested list that a chunk starts
131				// inside isn't corrupted (and the hashed id stays faithful to the source).
132				text := strings.TrimRight(c.Text, "\n")
133				records = append(records, docRecord{
134					ID:         docRecordID(rel, c.StartLine, text),
135					Path:       rel,
136					Heading:    firstHeading(text),
137					Line:       c.StartLine,
138					Text:       text,
139					Historical: historical,
140				})
141			}
142			return nil
143		})
144		return records, files, warnings, err
145	}
146	
147	func docFileHistorical(path, text string) bool {
148		lowerPath := "/" + strings.ToLower(filepath.ToSlash(path)) + "/"
149		for _, marker := range []string{"/archive/", "/historical/", "/outdated/", "/deprecated/"} {
150			if strings.Contains(lowerPath, marker) {
151				return true
152			}
153		}
154		markerText := strings.ToLower(text)
155		if len(markerText) > 2000 {
156			markerText = markerText[:2000]
157		}
158		return strings.Contains(markerText, "<!-- entire-brain-status: historical -->") ||
159			strings.Contains(markerText, "<!-- entire-brain-status: superseded -->")
160	}
