25	// retrievalCaveat is a machine-readable reason an agent must verify a memory
26	// result against current evidence before relying on it.
27	type retrievalCaveat struct {
28		Kind       string   `json:"kind"`
29		Message    string   `json:"message"`
30		Paths      []string `json:"paths,omitempty"`
31		ReviewID   string   `json:"review_id,omitempty"`
32		Action     string   `json:"action,omitempty"`
33		Confidence float64  `json:"confidence,omitempty"`
34	}
35	
36	type factReviewGroup struct {
37		ID        string
38		Facts     []factRecord
39		Proposals []factProposal
40	}
41	
42	// buildFactReviewGroups turns the pending proposal graph into stable connected
43	// components. Only valid proposals between two active facts affect retrieval;
44	// stale queue entries remain available to the review command but cannot hide or
45	// relabel an otherwise independent fact.
46	func buildFactReviewGroups(facts []factRecord, proposals []factProposal) []factReviewGroup {
47		if len(proposals) == 0 {
48			return nil
49		}
50		active := make(map[string]factRecord, len(facts))
51		for _, fact := range facts {
52			if fact.Status == factStatusActive {
53				active[fact.ID] = fact
54			}
55		}
56	
57		parent := make(map[string]string)
58		// ITERATIVE path compression. The recursive form recursed once per link in
59		// the parent chain, so a long chain was bounded only by the stack. Union by
60		// smaller id keeps chains short in practice, which is why this has not
61		// bitten -- but "short in practice" is not a bound, and the iterative form
62		// costs nothing and has one.
63		findRoot := func(id string) string {
64			p, ok := parent[id]
65			if !ok {
66				parent[id] = id
67				return id
68			}
69			// Walk to the root, remembering the path.
70			root := id
71			var path []string
72			for {
73				p, ok = parent[root]
74				if !ok || p == root {
75					if !ok {
76						parent[root] = root
77					}
78					break
79				}
80				path = append(path, root)
81				root = p
82			}
83			// Point every node on the path straight at the root.
84			for _, node := range path {
85				parent[node] = root
86			}
87			return root
88		}
89		union := func(a, b string) {
90			ra, rb := findRoot(a), findRoot(b)
91			if ra == rb {
92				return
93			}
94			if ra < rb {
95				parent[rb] = ra
96			} else {
97				parent[ra] = rb
98			}
99		}
100	
101		validByIdentity := make(map[string]factProposal, len(proposals))
102		for _, proposal := range proposals {
103			if proposal.Action != factActionMerge && proposal.Action != factActionSupersede {
104				continue
105			}
106			if proposal.CandidateID == proposal.TargetID {
107				continue
108			}
109			if _, ok := active[proposal.CandidateID]; !ok {
110				continue
111			}
112			if _, ok := active[proposal.TargetID]; !ok {
113				continue
114			}
115			key := factProposalIdentityKey(proposal)
116			if prior, ok := validByIdentity[key]; !ok || proposal.Confidence > prior.Confidence {
117				validByIdentity[key] = proposal
118			}
119			union(proposal.CandidateID, proposal.TargetID)
120		}
121		valid := make([]factProposal, 0, len(validByIdentity))
122		for _, proposal := range validByIdentity {
123			valid = append(valid, proposal)
124		}
125		if len(valid) == 0 {
126			return nil
127		}
128	
129		idsByRoot := make(map[string][]string)
130		for id := range parent {
131			root := findRoot(id)
132			idsByRoot[root] = append(idsByRoot[root], id)
133		}
134		proposalsByRoot := make(map[string][]factProposal)
135		for _, proposal := range valid {
136			root := findRoot(proposal.CandidateID)
137			proposalsByRoot[root] = append(proposalsByRoot[root], proposal)
138		}
139	
140		groups := make([]factReviewGroup, 0, len(idsByRoot))
141		for root, ids := range idsByRoot {
142			sort.Strings(ids)
143			groupProposals := proposalsByRoot[root]
144			sort.Slice(groupProposals, func(i, j int) bool {
145				return factProposalIdentityKey(groupProposals[i]) < factProposalIdentityKey(groupProposals[j])
146			})
147			group := factReviewGroup{ID: factReviewID(groupProposals[0]), Proposals: groupProposals}
148			for _, id := range ids {
149				group.Facts = append(group.Facts, active[id])
150			}
151			groups = append(groups, group)
152		}
153		sort.Slice(groups, func(i, j int) bool { return groups[i].ID < groups[j].ID })
154		return groups
155	}
156	
157	func factProposalIdentityKey(proposal factProposal) string {
158		return proposal.Action + "\x00" + proposal.CandidateID + "\x00" + proposal.TargetID
159	}
160	
161	func factReviewID(proposal factProposal) string {
162		sum := sha256.Sum256([]byte(factProposalIdentityKey(proposal)))
163		return "review:" + hex.EncodeToString(sum[:8])
164	}
165	
166	func indexFactReviewGroups(groups []factReviewGroup) (map[string]factReviewGroup, map[string]factReviewGroup) {
167		byID := make(map[string]factReviewGroup, len(groups))
168		byFactID := make(map[string]factReviewGroup)
169		for _, group := range groups {
170			for _, proposal := range group.Proposals {
171				byID[factReviewID(proposal)] = group
172			}
173			for _, fact := range group.Facts {
174				byFactID[fact.ID] = group
175			}
176		}
177		return byID, byFactID
178	}
