180	// guardedFactCandidateLimit reserves exactly enough ranked rows to backfill the
181	// requested limit if every valid pending review component collapses. Ranking
182	// more rows cannot improve the guarded top-N, and ranking the whole fact corpus
183	// creates avoidable conversions and allocations when no review is pending.
184	func guardedFactCandidateLimit(facts []factRecord, proposals []factProposal, limit int) int {
185		return guardedFactCandidateLimitForGroups(len(facts), buildFactReviewGroups(facts, proposals), limit)
186	}
187	
188	func guardedFactCandidateLimitForGroups(factCount int, groups []factReviewGroup, limit int) int {
189		if limit <= 0 || factCount == 0 {
190			return 0
191		}
192		if limit >= factCount {
193			return factCount
194		}
195		reserve := 0
196		for _, group := range groups {
197			reserve += len(group.Facts) - 1
198			if reserve >= factCount-limit {
199				return factCount
200			}
201		}
202		return limit + reserve
203	}
