205	// guardUnifiedFactResults collapses every pending proposal component into one
206	// explicit review result and annotates current-code drift. It preserves the
207	// first ranked position and best score of each component, then backfills from
208	// the expanded candidate set up to limit.
209	func guardUnifiedFactResults(repoDir string, facts []factRecord, proposals []factProposal, ranked []unifiedResult, limit int) []unifiedResult {
210		return guardUnifiedFactResultsWithGroups(repoDir, facts, buildFactReviewGroups(facts, proposals), ranked, limit)
211	}
212	
213	func guardUnifiedFactResultsWithGroups(repoDir string, facts []factRecord, groups []factReviewGroup, ranked []unifiedResult, limit int) []unifiedResult {
214		if limit <= 0 || len(ranked) == 0 {
215			return ranked
216		}
217		factByID := make(map[string]factRecord, len(facts))
218		for _, fact := range facts {
219			factByID[fact.ID] = fact
220		}
221		reviewByFactID := make(map[string]factReviewGroup)
222		for _, group := range groups {
223			for _, fact := range group.Facts {
224				reviewByFactID[fact.ID] = group
225			}
226		}
227		bestReviewScore := make(map[string]float64)
228		for _, result := range ranked {
229			if group, ok := reviewByFactID[result.ID]; ok && result.Score > bestReviewScore[group.ID] {
230				bestReviewScore[group.ID] = result.Score
231			}
232		}
233	
234		emittedReviews := make(map[string]bool)
235		out := make([]unifiedResult, 0, min(limit, len(ranked)))
236		for _, result := range ranked {
237			if result.Source == "fact" {
238				if group, ok := reviewByFactID[result.ID]; ok {
239					if emittedReviews[group.ID] {
240						continue
241					}
242					emittedReviews[group.ID] = true
243					review := factReviewToUnified(repoDir, group)
244					review.Score = bestReviewScore[group.ID]
245					out = append(out, review)
246				} else if fact, ok := factByID[result.ID]; ok {
247					out = append(out, annotateFactLocusTrust(repoDir, fact, result))
248				} else {
249					out = append(out, result)
250				}
251			} else {
252				out = append(out, result)
253			}
254			if len(out) >= limit {
255				break
256			}
257		}
258		return out
259	}
