261	func factReviewToUnified(repoDir string, group factReviewGroup) unifiedResult {
262		paths := make(map[string]struct{})
263		relatedIDs := make([]string, 0, len(group.Facts))
264		statements := make([]string, 0, len(group.Facts))
265		var drift []string
266		for _, fact := range group.Facts {
267			relatedIDs = append(relatedIDs, fact.ID)
268			statements = append(statements, fmt.Sprintf("%s says %q", fact.ID, fact.Text))
269			for _, path := range fact.Paths {
270				paths[path] = struct{}{}
271			}
272			drift = append(drift, factLocusDrift(repoDir, fact)...)
273		}
274		sort.Strings(relatedIDs)
275		sort.Strings(statements)
276	
277		actions := make([]string, 0, len(group.Proposals))
278		for _, proposal := range group.Proposals {
279			actions = append(actions, fmt.Sprintf("%s %s -> %s (confidence %.2f)", proposal.Action, proposal.CandidateID, proposal.TargetID, proposal.Confidence))
280		}
281		caveat := factReviewCaveat(group)
282		text := "Pending fact review. " + caveat.Message + " Facts: " + strings.Join(statements, "; ") +
283			". Proposed actions: " + strings.Join(actions, "; ") + "."
284		result := unifiedResult{
285			Source:               "fact-review",
286			ID:                   group.ID,
287			Path:                 strings.Join(sortedStringSet(paths), ","),
288			Heading:              "pending fact review",
289			Text:                 text,
290			VerificationRequired: true,
291			Caveats:              []retrievalCaveat{caveat},
292			RelatedIDs:           relatedIDs,
293		}
294		if drift = uniqueSortedStrings(drift); len(drift) > 0 {
295			result.Caveats = append(result.Caveats, staleLocusCaveat(drift))
296		}
297		return result
298	}
