300	func annotateExplicitFactReview(result unifiedResult, group factReviewGroup) unifiedResult {
301		result.VerificationRequired = true
302		// group.Facts is already in ascending fact-ID order (buildFactReviewGroups
303		// sorts the component's ids first), so filtering out the current fact leaves
304		// related sorted without an extra sort — same invariant factsPendingReview
305		// relies on.
306		related := make([]string, 0, len(group.Facts)-1)
307		for _, fact := range group.Facts {
308			if fact.ID != result.ID {
309				related = append(related, fact.ID)
310			}
311		}
312		result.RelatedIDs = related
313		result.Caveats = append(result.Caveats, factReviewCaveat(group))
314		return result
315	}
