317	func factReviewCaveat(group factReviewGroup) retrievalCaveat {
318		message := "A pending merge proposal may represent duplicate or distinct facts; verify the relationship before treating the statements as independent."
319		for _, proposal := range group.Proposals {
320			if proposal.Action == factActionSupersede {
321				message = "A pending supersede proposal indicates a potential contradiction; verify the related statements before relying on either one."
322				break
323			}
324		}
325		caveat := retrievalCaveat{
326			Kind:     retrievalCaveatUnresolvedReview,
327			Message:  message,
328			ReviewID: group.ID,
329		}
330		if len(group.Proposals) == 1 {
331			caveat.Action = group.Proposals[0].Action
332			caveat.Confidence = group.Proposals[0].Confidence
333		}
334		return caveat
335	}
