337	// factReviewNotice is the per-fact trust annotation for surfaces whose results
338	// are factRecords rather than unifiedResults (recall, brief). Those listings
339	// keep their record shape — no collapse into a fact-review row — so the pending
340	// state rides alongside, keyed by fact id like locus drift.
341	type factReviewNotice struct {
342		ReviewID   string   `json:"review_id"`
343		Action     string   `json:"action,omitempty"`
344		Confidence float64  `json:"confidence,omitempty"`
345		Message    string   `json:"message"`
346		RelatedIDs []string `json:"related_ids,omitempty"`
347	}
348	
349	// factReviewQueueUnavailableWarning mirrors the unified path's
350	// proposal_state_unavailable caveat for the facts-shaped surfaces.
351	const factReviewQueueUnavailableWarning = "fact review queue unreadable; verify fact consistency before relying on these facts"
352	
353	// factsPendingReview maps each surfaced fact that participates in a pending
354	// review component to its review notice. facts is the full branch set (group
355	// membership must not depend on the caller's scope/kind/locus filters), so
356	// building the review groups is O(facts + proposals); only the final
357	// annotation loop over surfaced is O(page). The early return keeps that full
358	// scan off the hot path whenever nothing was surfaced or no proposals exist.
359	func factsPendingReview(facts []factRecord, proposals []factProposal, surfaced []factRecord) map[string]factReviewNotice {
360		if len(surfaced) == 0 || len(proposals) == 0 {
361			return nil
362		}
363		_, byFactID := indexFactReviewGroups(buildFactReviewGroups(facts, proposals))
364		if len(byFactID) == 0 {
365			return nil
366		}
367		out := map[string]factReviewNotice{}
368		for _, fact := range surfaced {
369			group, ok := byFactID[fact.ID]
370			if !ok {
371				continue
372			}
373			caveat := factReviewCaveat(group)
374			// group.Facts is already in ascending fact-ID order (buildFactReviewGroups
375			// sorts the component's ids before materializing facts), so filtering out
376			// the current fact leaves related sorted without an extra sort.
377			related := make([]string, 0, len(group.Facts)-1)
378			for _, other := range group.Facts {
379				if other.ID != fact.ID {
380					related = append(related, other.ID)
381				}
382			}
383			out[fact.ID] = factReviewNotice{
384				ReviewID:   group.ID,
385				Action:     caveat.Action,
386				Confidence: caveat.Confidence,
387				Message:    caveat.Message,
388				RelatedIDs: related,
389			}
390		}
391		if len(out) == 0 {
392			return nil
393		}
394		return out
395	}
396	
397	// factReviewNoticeLine renders a notice for the human-readable fact listings,
398	// shared by recall and brief so the two surfaces stay in lockstep.
399	func factReviewNoticeLine(notice factReviewNotice) string {
400		line := "⚠ pending fact review " + notice.ReviewID
401		if notice.Action != "" {
402			line += fmt.Sprintf(" (%s, confidence %.2f)", notice.Action, notice.Confidence)
403		}
404		if len(notice.RelatedIDs) > 0 {
405			line += ": verify against " + strings.Join(notice.RelatedIDs, ", ")
406		}
407		return line
408	}
