48	// the most recent facts (no scoring), which makes `recall ""` a useful "what do
49	// you know about this branch" listing.
50	func rankFacts(facts []factRecord, query string, limit int, includeAll bool) []factRecord {
51		if limit <= 0 {
52			limit = 10
53		}
54		candidates := make([]factRecord, 0, len(facts))
55		for _, f := range facts {
56			if !includeAll && f.Status != factStatusActive {
57				continue
58			}
59			candidates = append(candidates, f)
60		}
61	
62		if strings.TrimSpace(query) == "" {
63			sort.SliceStable(candidates, func(i, j int) bool {
64				return candidates[i].UpdatedAt.After(candidates[j].UpdatedAt)
65			})
66			if len(candidates) > limit {
