99	// combines a whole-query substring match, per-term overlap, and a bonus when a
100	// term hits a taxonomy path (a path match is a strong topical signal).
101	func factQueryScore(record factRecord, query string) int {
102		haystack := record.Text + " " + strings.Join(record.Paths, " ")
103		score := 0
104		if historyTextMatchesQuery(haystack, query) {
105			score += 200
106		}
107		terms := historyQueryTerms(query)
108		if len(terms) == 0 {
109			return score
110		}
111		normalizedText := normalizeHistorySearchText(haystack)
112		normalizedPaths := normalizeHistorySearchText(strings.Join(record.Paths, " "))
113		matches := 0
114		for _, term := range terms {
115			if strings.Contains(normalizedText, term) {
116				matches++
117				score += 10
118				if strings.Contains(normalizedPaths, term) {
119					score += 8
120				}
121			}
122		}
123		if matches == 0 && score < 200 {
124			return 0
125		}
126		if matches == len(terms) {
127			score += 20 // all query terms present
128		}
129		return score
130	}
