154	// A brain accumulates, so relevance alone keeps surfacing the oldest matching
155	// answer forever. These tests pin the three properties that make time-weighting
156	// safe to add to ranking: it only ever reorders, it never invents an age it does
157	// not have, and it costs nothing to compute.
158	
159	func TestRecencyMultiplierHalvesTowardTheFloor(t *testing.T) {
160		half := 90 * 24 * time.Hour
161		cases := []struct {
162			name string
163			age  time.Duration
164			want float64
165		}{
166			{"brand new", 0, recencyCeiling},
167			{"one half-life", half, recencyFloor + (recencyCeiling-recencyFloor)/2},
168			{"two half-lives", 2 * half, recencyFloor + (recencyCeiling-recencyFloor)/4},
169			{"ten half-lives", 10 * half, recencyFloor + (recencyCeiling-recencyFloor)/1024},
170		}
171		for _, tc := range cases {
172			got := recencyMultiplier(tc.age, half)
173			if math.Abs(got-tc.want) > 1e-9 {
174				t.Fatalf("%s: multiplier = %v, want %v", tc.name, got, tc.want)
175			}
176			if got < recencyFloor || got > recencyCeiling {
177				t.Fatalf("%s: multiplier %v escaped [%v, %v]", tc.name, got, recencyFloor, recencyCeiling)
178			}
179		}
180	}
