182	func TestRecencyNeverInventsAnAgeItDoesNotHave(t *testing.T) {
183		now := time.Date(2026, 9, 21, 12, 0, 0, 0, time.UTC)
184		half := 90 * 24 * time.Hour
185	
186		// Classic history records carry no timestamp. Treating "undated" as "old"
187		// would silently demote a whole corpus for a property it never claimed.
188		for _, undated := range []string{"", "not-a-timestamp", "2026/09/21"} {
189			got, dated := recencyMultiplierFor(undated, now, half)
190			if dated {
191				t.Fatalf("%q should not count as dated", undated)
192			}
193			if got != recencyNeutralMultiplier {
194				t.Fatalf("%q: multiplier = %v, want the neutral %v", undated, got, recencyNeutralMultiplier)
195			}
196		}
197	
198		// A future timestamp is a broken clock, not a very fresh record, and must
199		// not mint a multiplier above the ceiling.
200		future := now.Add(365 * 24 * time.Hour).Format(time.RFC3339)
201		got, dated := recencyMultiplierFor(future, now, half)
202		if !dated {
203			t.Fatal("a parseable future timestamp is still a timestamp")
204		}
205		if got > recencyCeiling {
206			t.Fatalf("future timestamp produced %v, above the ceiling %v", got, recencyCeiling)
207		}
208	}
