216			{ID: "fact:old", Score: 0.050, CreatedAt: stamp(3 * 365 * 24 * time.Hour)},
217			{ID: "fact:fresh", Score: 0.049, CreatedAt: stamp(24 * time.Hour)},
218			{ID: "history:undated", Score: 0.048},
