229			t.Fatalf("a day-old record scoring 0.049 should outrank a three-year-old scoring 0.050; got %q first", results[0].ID)
230		}
231		for _, r := range results {
232			if r.Score <= 0 {
233				t.Fatalf("%s: score %v — weighting must not zero a result out", r.ID, r.Score)
234			}
235		}
