238	func TestRecencyCannotOverwhelmRelevance(t *testing.T) {
239		now := time.Date(2026, 9, 21, 12, 0, 0, 0, time.UTC)
240		half := 90 * 24 * time.Hour
241	
242		// The spread is ceiling/floor = 5x. A match five times stronger must still
243		// win however old it is, or "bias" has quietly become "filter".
244		results := []unifiedResult{
245			{ID: "fact:ancient-but-exact", Score: 1.0, CreatedAt: now.Add(-50 * 365 * 24 * time.Hour).Format(time.RFC3339)},
246			{ID: "fact:fresh-but-weak", Score: 1.0 / (recencyCeiling / recencyFloor) * 0.99, CreatedAt: now.Format(time.RFC3339)},
247		}
