293		}
294	
295		// On: the fresher record takes the lead on a near-tie.
296		on := fused()
297		applyRecency(on, now, defaultRecencyHalfLife)
298		if on[0].ID != "fact:fresh" {
299			t.Fatalf("with recency the day-old record should lead; got %q", on[0].ID)
300		}
