302		// And the default in retrievalOptions is the zero value, so every existing
303		// caller keeps the ordering it has today.
304		var defaults retrievalOptions
305		if defaults.Recency {
306			t.Fatal("recency must default to off")
307		}
308		if defaults.RecencyHalfLife != 0 {
309			t.Fatalf("half-life must default to zero so the package default applies, got %v", defaults.RecencyHalfLife)
310		}
311	}
